#!/usr/bin/env bash
# Validate a commit message against the company baseline.
# Usage: validate_commit_msg.sh <file-with-message>
# Exit 0 if valid, 1 otherwise (errors on stderr).
set -uo pipefail

file="${1:?usage: validate_commit_msg.sh <message-file>}"
# Drop comment lines (git commit template) and trailing blank lines.
msg="$(grep -v '^#' "$file" | sed -e :a -e '/^\n*$/{$d;N;ba' -e '}')"
header="$(printf '%s\n' "$msg" | head -n1)"

# Commits generated by git itself are not ours to judge.
case "$header" in
  "Merge "*|"fixup! "*|"squash! "*|"amend! "*) exit 0 ;;
esac

errors=()
types='feat|fix|refactor|perf|test|docs|chore|ci|revert'
needs_ticket='^(feat|fix|refactor|perf|revert)$'
re="^($types)(\(([A-Z][A-Z0-9]+-[0-9]+)\))?(!)?: (.+)$"

if [[ ! "$header" =~ $re ]]; then
  errors+=("header must be '<type>(<TICKET>): <subject>' with type in: ${types//|/, }")
else
  type="${BASH_REMATCH[1]}"; ticket="${BASH_REMATCH[3]}"; subject="${BASH_REMATCH[5]}"
  if [[ "$type" =~ $needs_ticket && -z "$ticket" ]]; then
    errors+=("type '$type' requires a ticket: $type(ABC-123): ...")
  fi
  (( ${#header} > 72 )) && errors+=("header is ${#header} characters, max 72")
  [[ "$subject" =~ \.$ ]] && errors+=("subject must not end with a period")
  [[ "$subject" =~ ^[A-Z][a-z] ]] && errors+=("subject must start in lower case (imperative: 'add', not 'Add')")
  first="${subject%% *}"
  if [[ "$first" =~ (ed|ing)$ && ! "$first" =~ ^(embed|shed|speed|need|feed|seed|bring|ping|log)$ ]]; then
    errors+=("subject must use the imperative mood ('add', not '$first')")
  fi
  if [[ "$type" =~ $needs_ticket ]]; then
    body="$(printf '%s\n' "$msg" | tail -n +2)"
    [[ -n "$(printf '%s\n' "$msg" | sed -n 2p)" ]] && errors+=("leave a blank line after the header")
    for label in Why What Risk Tests; do
      grep -qE "^$label: ?\S" <<<"$body" || errors+=("body needs a '$label:' line")
    done
  fi
fi

if (( ${#errors[@]} )); then
  echo "commit message rejected (change-standards):" >&2
  printf '  - %s\n' "${errors[@]}" >&2
  echo "  header: $header" >&2
  echo "  format: see .ai/skills/change-standards/references/baseline.md" >&2
  exit 1
fi
exit 0
